Url) ?>/download?id=<?= (int)$file['id'] ?>"><?= e($file['original_name']) ?></a><br><?php endforeach; ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php endforeach; ?><section class="panel"><h3>Anexos</h3><?php if(!$record['files']): ?><p class="muted">Nenhum anexo.</p><?php else: ?><?php foreach($record['files'] as $f): ?><p><a class="text-link" href="<?= e($baseUrl) ?>/download?id=<?= (int)$f['id'] ?>"><?= e($f['original_name']) ?></a></p><?php endforeach; ?><?php endif; ?></section><?php if($record['signature']): ?><section class="panel"><h3>Confirmação do servidor</h3><p><?= e($record['signature']['name']) ?> · <?= date('d/m/Y H:i',strtotime($record['signature']['signed_at'])) ?></p><img class="signature-preview" src="<?= e($record['signature']['signature_data']) ?>" alt="Assinatura interna"></section><?php endif; ?>
